import Foundation

/// Strings are written in Russian in the code and serve as keys; English comes from en.lproj/Localizable.strings
/// (generated by scripts/l10n/make_strings.py from scripts/l10n/en.json). The interface takes the localization macOS
/// picks for the app at launch, like the menus and panels macOS draws for it, so the two never mix: the app's own
/// choice in Settings or in System Settings → Language & Region → Applications, otherwise the first of the Mac's
/// languages the app speaks (see InterfaceLanguage.swift).
public enum Localization {
    /// "ru" or "en" for this launch. A new choice takes effect after a restart.
    public static let current: String = {
        // A build without the app bundle has no translations: the keys are Russian.
        guard Bundle.main.path(forResource: "en", ofType: "lproj") != nil else { return "ru" }
        return InterfaceLanguage.running
    }()

    /// Call as early as possible at launch.
    public static func apply() {
        _ = current
    }

    static func string(_ key: String) -> String {
        bundle?.localizedString(forKey: key, value: key, table: nil) ?? key
    }

    private static let bundle: Bundle? = {
        guard current != "ru", let path = Bundle.main.path(forResource: current, ofType: "lproj") else { return nil }
        return Bundle(path: path)
    }()
}

/// Localized string. `key` is the Russian text; `%@` placeholders are filled with `args`.
public func L(_ key: String, _ args: CVarArg...) -> String {
    let text = Localization.string(key)
    return args.isEmpty ? text : String(format: text, arguments: args)
}
